bool DOMPluginArray::IsPdfViewerAvailable() {
  // Plugin inventory and navigator.pdfViewerEnabled describe the installed
  // viewer. A presentation-only fixture is available solely in synthetic tests.
  if (base::UxrConfig::GetInstance().Get("uxr-synthetic-device-tests") ==
          "true" &&
      base::UxrConfig::GetInstance().Get("uxr-plugins") == "chrome") {
    return true;
  }
  auto* data = GetPluginData();
  if (!data)
    return false;
