PublicKeyCredential::isUserVerifyingPlat.text:
PublicKeyCredential::isUserVerifyingPlatformAuthenticatorAvailable(
    ScriptState* script_state) {
  // Ignore calls if the current realm execution context is no longer valid,
  // e.g., because the responsible document was detached.
  if (!script_state->ContextIsValid()) {
    return ScriptPromise<IDLBoolean>::RejectWithDOMException(
        script_state,
        MakeGarbageCollected<DOMException>(DOMExceptionCode::kInvalidStateError,
                                           "Context is detached"));
  }

  auto* resolver =
      MakeGarbageCollected<ScriptPromiseResolver<IDLBoolean>>(script_state);
  auto promise = resolver->Promise();

  UseCounter::Count(
      resolver->GetExecutionContext(),
      WebFeature::
          kCredentialManagerIsUserVerifyingPlatformAuthenticatorAvailable);

  // A public platform name cannot install an authenticator. Keep the browser
  // capability query, callback timing and permission authority for real use.
  // A forced answer is only available to explicitly synthetic test fixtures.
  {
    std::string p_uv = base::UxrConfig::GetInstance().Get("uxr-webauthn-uvpaa");
    if (base::UxrConfig::GetInstance().Get("uxr-synthetic-device-tests") ==
            "true" &&
        !p_uv.empty()) {
      resolver->Resolve(p_uv == "true");
      return promise;
    }
  }

  auto* authenticator =
      CredentialManagerProxy::From(script_state)->Authenticator();
  authenticator->IsUserVerifyingPlatformAuthenticatorAvailable(
      BindOnce(&OnIsUserVerifyingComplete, WrapPersistent(resolver)));
  return promise;
}

void ApplyUxrAudioIsolation(.text:
void ApplyUxrAudioIsolation(AudioBus* bus, uint32_t frames, uint64_t seed) {
  if (!seed || bus->IsSilent())
    return;
  // A launch-stable rounding threshold on a 20-bit sample grid. Apply to the
  // graph's actual bus, before its consumers run: playback, OfflineAudioContext,
  // Analyser and AudioWorklet then receive the same samples. Never mutate
  // AudioBuffer getters or fabricate sample rates, latencies or device data.
  seed ^= seed >> 30;
  seed *= uint64_t{0xbf58476d1ce4e5b9};
  seed ^= seed >> 27;
  seed *= uint64_t{0x94d049bb133111eb};
  seed ^= seed >> 31;
  const double threshold = 0.25 + static_cast<double>(seed >> 11) * 0x1.0p-54;
  constexpr double kScale = 0x1.0p20;
  for (unsigned channel = 0; channel < bus->NumberOfChannels(); ++channel) {
    for (float& sample : bus->Channel(channel)->MutableSpan().first(frames)) {
      if (sample == 0 || !std::isfinite(sample) || std::abs(sample) >= 16)
        continue;
      // Signed zero, silence and exceptional values retain their native bits.
      // Exact grid samples are fixed points, including in-place fanout buses.
      const double magnitude = std::floor(std::abs(static_cast<double>(sample)) *
                                          kScale + threshold) / kScale;
      sample = std::copysign(static_cast<float>(magnitude), sample);
    }
  }
}

void AudioHandler::ProcessIfNecessary(.text:
void AudioHandler::ProcessIfNecessary(uint32_t frames_to_process) {
  DCHECK(Context()->IsAudioThread());

  if (!IsInitialized()) {
    return;
  }

  TRACE_EVENT2(TRACE_DISABLED_BY_DEFAULT("webaudio.audionode"),
               "AudioHandler::ProcessIfNecessary", "this",
               reinterpret_cast<void*>(this), "node type", NodeTypeName());

  // Ensure that we only process once per rendering quantum.
  // This handles the "fanout" problem where an output is connected to multiple
  // inputs.  The first time we're called during this time slice we process, but
  // after that we don't want to re-process, instead our output(s) will already
  // have the results cached in their bus;
  double current_time = Context()->currentTime();
  if (last_processing_time_ != current_time) {
    // important to first update this time because of feedback loops in the
    // rendering graph.
    last_processing_time_ = current_time;

    PullInputs(frames_to_process);

    bool silent_inputs = InputsAreSilent();
    if (silent_inputs && PropagatesSilence()) {
      SilenceOutputs();
      // AudioParams still need to be processed so that the value can be updated
      // if there are automations or so that the upstream nodes get pulled if
      // any are connected to the AudioParam.
      ProcessOnlyAudioParams(frames_to_process);
    } else {
      // Unsilence the outputs first because the processing of the node may
      // cause the outputs to go silent and we want to propagate that hint to
      // the downstream nodes.  (For example, a Gain node with a gain of 0 will
      // want to silence its output.)
      UnsilenceOutputs();
      base::TimeTicks process_start_time = base::TimeTicks::Now();
      Process(frames_to_process);
      const uint64_t isolation_seed = base::UxrConfig::GetInstance().AudioIsolationSeed();
      if (isolation_seed) {
        for (auto& output : outputs_)
          ApplyUxrAudioIsolation(output->Bus(), frames_to_process, isolation_seed);
      }
      base::TimeDelta process_duration =
          base::TimeTicks::Now() - process_start_time;
      uma_reporter_->AddProcessDuration(process_duration, frames_to_process);
    }

    if (!silent_inputs) {
      // Update `last_non_silent_time_` AFTER processing this block.
      // Doing it before causes `PropagateSilence()` to be one render
      // quantum longer than necessary.
      last_non_silent_time_ =
          (Context()->CurrentSampleFrame() + frames_to_process) /
          static_cast<double>(Context()->sampleRate());
    }

    if (!is_processing_) {
      SendLogMessage(__func__,
                     String::Format("=> (processing is alive [frames=%u])",
                                    frames_to_process));
      is_processing_ = true;
    }
  }
}

bool IsUxrVideoCodecAllowed(.text:
bool IsUxrVideoCodecAllowed(VideoCodec codec) {
  const char* key = nullptr;
  switch (codec) {
    case VideoCodec::kH264: key = "uxr-codec-h264"; break;
    case VideoCodec::kVP8: key = "uxr-codec-vp8"; break;
    case VideoCodec::kVP9: key = "uxr-codec-vp9"; break;
    case VideoCodec::kAV1: key = "uxr-codec-av1"; break;
    case VideoCodec::kHEVC: key = "uxr-codec-hevc"; break;
    default: return true;
  }
  const auto& config = base::UxrConfig::GetInstance();
  if (!config.Has(key))
    return true;
  const std::string value = config.Get(key);
  if (value == "native")
    return true;
  // SetAll validates the exact token grammar before this immutable policy is
  // published. The separators keep partial tokens from enabling a backend.
  return ("," + value + ",").find(",supported,") != std::string::npos;
}

