void DecoderSelector<StreamType>::Select.text:
void DecoderSelector<StreamType>::SelectDecoderInternal(
    SelectDecoderCB select_decoder_cb,
    typename Decoder::OutputCB output_cb,
    bool needs_new_decoders) {
  DVLOG(2) << __func__;
  DCHECK_CALLED_ON_VALID_SEQUENCE(sequence_checker_);
  DCHECK(select_decoder_cb);
  DCHECK(!select_decoder_cb_);
  select_decoder_cb_ = std::move(select_decoder_cb);
  output_cb_ = std::move(output_cb);
  config_ = traits_->GetDecoderConfig(stream_);

  TRACE_EVENT_BEGIN("media", kSelectDecoderTrace, GetTracingTrack(this), "type",
                    DemuxerStream::GetTypeName(StreamType), "config",
                    config_.AsHumanReadableString());

  if (!config_.IsValidConfig()) {
    DLOG(ERROR) << "Invalid stream config";
    ReturnSelectionError(DecoderStatus::Codes::kUnsupportedConfig);
    return;
  }

  if constexpr (StreamType == DemuxerStream::VIDEO) {
    if (!IsUxrVideoCodecAllowed(config_.codec())) {
      ReturnSelectionError(DecoderStatus::Codes::kUnsupportedConfig);
      return;
    }
  }

  if (needs_new_decoders) {
    decode_failure_reinit_cause_ = std::nullopt;
    ran_out_of_decoders_ = false;
    CreateDecoders();
  }

  GetAndInitializeNextDecoder();
}

media::VideoCodec VideoTrackRecorderImpl.text:
media::VideoCodec VideoTrackRecorderImpl::GetPreferredCodec(
    MediaTrackContainerType type) {
  for (const auto& supported_profile : GetVEASupportedProfiles()) {
    const media::VideoCodecProfile codec_profile = supported_profile.profile;
    for (auto& entry : kPreferredCodecAndVEAProfiles) {
      if (!media::IsUxrVideoCodecAllowed(entry.codec))
        continue;
      if (codec_profile >= entry.min_profile &&
          codec_profile <= entry.max_profile &&
          std::find(entry.supported_container_types.begin(),
                    entry.supported_container_types.end(),
                    type) != entry.supported_container_types.end()) {
        DVLOG(2) << "Accelerated codec found: "
                 << media::GetProfileName(codec_profile) << ", min_resolution: "
                 << supported_profile.min_resolution.ToString()
                 << ", max_resolution: "
                 << supported_profile.max_resolution.ToString()
                 << ", max_framerate: "
                 << supported_profile.max_framerate_numerator << "/"
                 << supported_profile.max_framerate_denominator;
        return entry.codec;
      }
    }
  }

  const bool mp4 = type == MediaTrackContainerType::kVideoMp4 ||
                   type == MediaTrackContainerType::kAudioMp4;
  for (media::VideoCodec codec : {media::VideoCodec::kVP8, media::VideoCodec::kVP9,
                                  media::VideoCodec::kAV1, media::VideoCodec::kH264}) {
    if (mp4 && codec == media::VideoCodec::kVP8)
      continue;
    if (codec == media::VideoCodec::kH264 && !mp4 &&
        type != MediaTrackContainerType::kVideoMatroska)
      continue;
    if (media::IsUxrVideoCodecAllowed(codec) && IsSoftwareEncoderAvailable(codec))
      return codec;
  }
  return media::VideoCodec::kUnknown;
}

