class EncoderAdapter :.text:
class EncoderAdapter : public webrtc::VideoEncoderFactory {
 public:
  explicit EncoderAdapter(
      std::unique_ptr<RTCVideoEncoderFactory> hardware_encoder_factory,
      StatsCollector::StoreProcessingStatsCB stats_callback)
      : hardware_encoder_factory_(std::move(hardware_encoder_factory)),
        stats_callback_(stats_callback) {
    if (hardware_encoder_factory_) {
      hardware_encoder_factory_->SetAvailableSoftwareFallbackCodecs(
          software_encoder_factory_.GetSupportedFormats());
    }
  }

  std::unique_ptr<webrtc::VideoEncoder> Create(
      const webrtc::Environment& env,
      const webrtc::SdpVideoFormat& format) override {
    if (!UxrRtcFormatAllowed(format))
      return nullptr;
    if (!WebRTCFormatToCodecProfile(format)) {
      LOG(ERROR) << "Unsupported SDP format: " << format.name;
      return nullptr;
    }
    const bool supported_in_hardware =
        IsFormatSupported(hardware_encoder_factory_.get(), format);
    bool allow_h264_profile_fallback = false;
    // Special handling of H264 hardware encoder fallback during encoding when
    // high profile is requested. However if hardware encoding is not supported,
    // trust supported formats reported by |software_encoder_factory_| and do
    // not allow profile mismatch when only software encoder factory is used for
    // creating the simulcast encoder adapter.
    if (base::EqualsCaseInsensitiveASCII(format.name, webrtc::kH264CodecName) &&
        supported_in_hardware) {
      allow_h264_profile_fallback = IsFormatSupported(
          &software_encoder_factory_,
          webrtc::CreateH264Format(
              webrtc::H264Profile::kProfileConstrainedBaseline,
              webrtc::H264Level::kLevel1_1, "1"));
    }
    const bool supported_in_software =
        allow_h264_profile_fallback ||
        IsFormatSupported(&software_encoder_factory_, format);

    if (!supported_in_software && !supported_in_hardware)
      return nullptr;

    VideoEncoderFactory* primary_factory =
        supported_in_hardware ? static_cast<webrtc::VideoEncoderFactory*>(
                                    hardware_encoder_factory_.get())
                              : &software_encoder_factory_;
    VideoEncoderFactory* fallback_factory =
        supported_in_hardware && supported_in_software
            ? &software_encoder_factory_
            : nullptr;
    std::unique_ptr<webrtc::VideoEncoder> encoder =
        std::make_unique<webrtc::SimulcastEncoderAdapter>(
            env, primary_factory, fallback_factory, format);

    return std::make_unique<StatsCollectingEncoder>(format, std::move(encoder),
                                                    stats_callback_);
  }

  std::vector<webrtc::SdpVideoFormat> GetSupportedFormats() const override {
    std::vector<webrtc::SdpVideoFormat> software_formats =
        software_encoder_factory_.GetSupportedFormats();
    return FilterUxrRtcFormats(hardware_encoder_factory_
               ? MergeFormats(software_formats,
                              hardware_encoder_factory_->GetSupportedFormats())
               : software_formats);
  }

  webrtc::VideoEncoderFactory::CodecSupport QueryCodecSupport(
      const webrtc::SdpVideoFormat& format,
      std::optional<std::string> scalability_mode,
      std::optional<webrtc::Resolution> resolution) const override {
    if (!UxrRtcFormatAllowed(format))
      return {};
    webrtc::VideoEncoderFactory::CodecSupport codec_support =
        hardware_encoder_factory_
            ? hardware_encoder_factory_->QueryCodecSupport(
                  format, scalability_mode, resolution)
            : webrtc::VideoEncoderFactory::CodecSupport();
    if (!codec_support.is_supported) {
      codec_support = software_encoder_factory_.QueryCodecSupport(
          format, scalability_mode, resolution);
    }
    return codec_support;
  }

 private:
  webrtc::InternalEncoderFactory software_encoder_factory_;
  const std::unique_ptr<RTCVideoEncoderFactory> hardware_encoder_factory_;
  StatsCollector::StoreProcessingStatsCB stats_callback_;
}

class DecoderAdapter :.text:
class DecoderAdapter : public webrtc::VideoDecoderFactory {
 public:
  explicit DecoderAdapter(
      std::unique_ptr<webrtc::VideoDecoderFactory> hardware_decoder_factory,
      StatsCollector::StoreProcessingStatsCB stats_callback)
      : hardware_decoder_factory_(std::move(hardware_decoder_factory)),
        stats_callback_(stats_callback) {}

  std::unique_ptr<webrtc::VideoDecoder> Create(
      const webrtc::Environment& env,
      const webrtc::SdpVideoFormat& format) override {
    if (!UxrRtcFormatAllowed(format))
      return nullptr;
    std::unique_ptr<webrtc::VideoDecoder> software_decoder =
        CreateDecoder(&software_decoder_factory_, env, format);

    std::unique_ptr<webrtc::VideoDecoder> hardware_decoder =
        CreateDecoder(hardware_decoder_factory_.get(), env, format);

    if (!software_decoder && !hardware_decoder)
      return nullptr;

    return std::make_unique<StatsCollectingDecoder>(
        format,
        Wrap(env, std::move(software_decoder), std::move(hardware_decoder)),
        stats_callback_);
  }

  std::vector<webrtc::SdpVideoFormat> GetSupportedFormats() const override {
    std::vector<webrtc::SdpVideoFormat> software_formats =
        software_decoder_factory_.GetSupportedFormats();
    return FilterUxrRtcFormats(hardware_decoder_factory_
               ? MergeFormats(software_formats,
                              hardware_decoder_factory_->GetSupportedFormats())
               : software_formats);
  }

  webrtc::VideoDecoderFactory::CodecSupport QueryCodecSupport(
      const webrtc::SdpVideoFormat& format,
      bool reference_scaling,
      std::optional<webrtc::Resolution> resolution) const override {
    if (!UxrRtcFormatAllowed(format))
      return {};
    webrtc::VideoDecoderFactory::CodecSupport codec_support =
        hardware_decoder_factory_
            ? hardware_decoder_factory_->QueryCodecSupport(
                  format, reference_scaling, resolution)
            : webrtc::VideoDecoderFactory::CodecSupport();
    if (!codec_support.is_supported) {
      codec_support = software_decoder_factory_.QueryCodecSupport(
          format, reference_scaling, resolution);
    }
    return codec_support;
  }

 private:
  webrtc::InternalDecoderFactory software_decoder_factory_;
  const std::unique_ptr<webrtc::VideoDecoderFactory> hardware_decoder_factory_;
  StatsCollector::StoreProcessingStatsCB stats_callback_;
}

bool UxrFontFamilyIsGeneric(.text:
bool UxrFontFamilyIsGeneric(const AtomicString& family) {
  const std::string name = family.GetString().ToAsciiLower().Utf8();
  static constexpr const char* kGenericFamilies[] = {
      "serif",       "sans-serif", "monospace",    "cursive",
      "fantasy",     "system-ui",  "math",         "emoji",
      "fangsong",    "ui-serif",   "ui-sans-serif", "ui-monospace",
      "ui-rounded",  "ui-fangsong", "-webkit-body",
      "-webkit-pictograph", "-webkit-system-font", "-webkit-control"};
  for (const char* generic : kGenericFamilies) {
    if (name == generic)
      return true;
  }
  return false;
}

const char* UxrSystemFontSubstitute(.text:
const char* UxrSystemFontSubstitute(const AtomicString& family) {
  if (!base::UxrConfig::GetInstance().Get("uxr-font-policy").empty())
    return nullptr;
  if (base::UxrConfig::GetInstance().Get("uxr-synthetic-device-tests") != "true")
    return nullptr;
  const std::string persona =
      base::UxrConfig::GetInstance().Get("uxr-platform");
  if ((!base::EqualsCaseInsensitiveASCII(persona, "windows") &&
       !base::EqualsCaseInsensitiveASCII(persona, "win32")) ||
      !base::UxrConfig::GetInstance().Get("uxr-font-whitelist").empty()) {
    return nullptr;
  }

  static constexpr struct {
    const char* generic;
    const char* family;
  } kWindowsGenericFamilies[] = {
      {"system-ui", "Segoe UI"},
      {"sans-serif", "Arial"},
      {"serif", "Times New Roman"},
      {"monospace", "Consolas"},
      {"emoji", "Segoe UI Emoji"},
      {"cursive", "Comic Sans MS"},
      {"fantasy", "Impact"},
      {"math", "Cambria Math"},
      {"ui-monospace", "Consolas"},
      {"ui-serif", "Times New Roman"},
      {"ui-sans-serif", "Segoe UI"},
      {"ui-rounded", "Segoe UI"},
      {"-webkit-body", "Times New Roman"},
      {"-webkit-pictograph", "Segoe UI Emoji"},
      {"-webkit-system-font", "Segoe UI"},
      {"-webkit-control", "Segoe UI"}};
  const std::string requested = family.GetString().Utf8();
  for (const auto& entry : kWindowsGenericFamilies) {
    if (base::EqualsCaseInsensitiveASCII(entry.generic, requested))
      return entry.family;
  }
  return nullptr;
}

bool UxrFontFamilyAllowed(.text:
bool UxrFontFamilyAllowed(const AtomicString& family) {
  // Explicit policy uses the resolved family below, not the requested alias.
  if (!base::UxrConfig::GetInstance().Get("uxr-font-policy").empty())
    return true;
  if (base::UxrConfig::GetInstance().Get("uxr-synthetic-device-tests") != "true")
    return true;
  if (family.empty() || UxrFontFamilyIsGeneric(family))
    return true;

  const std::string requested = family.GetString().Utf8();
  const std::string whitelist =
      base::UxrConfig::GetInstance().Get("uxr-font-whitelist");
  if (!whitelist.empty()) {
    for (const std::string& entry : base::SplitString(
             whitelist, ",", base::TRIM_WHITESPACE,
             base::SPLIT_WANT_NONEMPTY)) {
      if (base::EqualsCaseInsensitiveASCII(entry, requested))
        return true;
    }
    return false;
  }

  const std::string persona =
      base::UxrConfig::GetInstance().Get("uxr-platform");
  if (!base::EqualsCaseInsensitiveASCII(persona, "windows") &&
      !base::EqualsCaseInsensitiveASCII(persona, "win32")) {
    return true;
  }

  // Keep the default Windows persona aligned with assets/fonts. The list uses
  // family names from the bundled files' OpenType name tables, including
  // typographic subfamilies that Fontconfig exposes as selectable families.
  static constexpr const char* kBundledWindowsFamilies[] = {
      "Arial", "Arial Black", "Arial Narrow", "Arial Rounded MT Bold",
      "Book Antiqua", "Bookman Old Style", "Calibri", "Calibri Light",
      "Cambria", "Cambria Math", "Century", "Century Gothic",
      "Century Schoolbook", "Comic Sans MS", "Consolas", "Courier New",
      "Garamond", "Georgia", "Impact", "Lucida Bright",
      "Lucida Calligraphy", "Lucida Console", "Lucida Fax",
      "Lucida Handwriting", "Lucida Sans", "Lucida Sans Typewriter",
      "Lucida Sans Unicode", "Microsoft Sans Serif", "Monotype Corsiva",
      "MS Gothic", "MS PGothic", "MS Reference Sans Serif", "MS UI Gothic",
      "Palatino Linotype", "Segoe Print",
      "Segoe Script", "Segoe UI", "Segoe UI Black", "Segoe UI Emoji",
      "Segoe UI Historic", "Segoe UI Light", "Segoe UI Semibold",
      "Segoe UI Semilight", "Segoe UI Symbol", "Tahoma", "Times New Roman",
      "Trebuchet MS", "Verdana", "Wingdings", "Wingdings 2", "Wingdings 3",
      "ＭＳ ゴシック", "ＭＳ Ｐゴシック"};
  for (const char* allowed : kBundledWindowsFamilies) {
    if (base::EqualsCaseInsensitiveASCII(allowed, requested))
      return true;
  }
  return false;
}

const FontPlatformData* FontCache::GetFo.text:
const FontPlatformData* FontCache::GetFontPlatformData(
    const FontDescription& font_description,
    const FontFaceCreationParams& creation_params,
    AlternateFontName alternate_font_name) {
  // Only CSS family lookup substitutes generics; src:local() stays exact.
  if (creation_params.CreationType() == kCreateFontByFamily &&
      (alternate_font_name == AlternateFontName::kAllowAlternate ||
       alternate_font_name == AlternateFontName::kNoAlternate)) {
    if (const char* ux_sub = UxrSystemFontSubstitute(creation_params.Family())) {
      if (const FontPlatformData* data = GetFontPlatformData(
              font_description, FontFaceCreationParams(AtomicString(ux_sub)),
              alternate_font_name)) {
        return data;
      }
    }
  }

  // Filter native families and src:local() probes. Downloaded faces and
  // last-resort fallback retain normal Blink behavior.
  if (creation_params.CreationType() == kCreateFontByFamily &&
      alternate_font_name != AlternateFontName::kLastResort &&
      !UxrFontFamilyAllowed(creation_params.Family())) {
    return nullptr;
  }

  TRACE_EVENT0("fonts", "FontCache::GetFontPlatformData");

#if !BUILDFLAG(IS_MAC)
  if (creation_params.CreationType() == kCreateFontByFamily &&
      creation_params.Family() == font_family_names::kSystemUi) {
    return SystemFontPlatformData(font_description);
  }
#endif

  const FontPlatformData* data = font_platform_data_cache_.GetOrCreateFontPlatformData(
      this, font_description, creation_params, alternate_font_name);
  if (data && !IsUxrFontFamilyAllowed(data->FontFamilyName()))
    return nullptr;
  return data;
}

bool FontCache::IsUxrFontFamilyAllowed(.text:
bool FontCache::IsUxrFontFamilyAllowed(const String& family) {
  const auto& config = base::UxrConfig::GetInstance();
  if (config.Get("uxr-font-policy") != "restricted")
    return true;
  const std::string actual = family.Utf8();
  for (const auto& entry : base::SplitString(config.Get("uxr-font-whitelist"), ",",
                                            base::TRIM_WHITESPACE,
                                            base::SPLIT_WANT_NONEMPTY)) {
    if (base::EqualsCaseInsensitiveASCII(entry, actual))
      return true;
  }
  return false;
}

const SimpleFontData* FontCache::UxrRest.text:
const SimpleFontData* FontCache::UxrRestrictedLastResortFont(
    const FontDescription& description) {
  const auto& config = base::UxrConfig::GetInstance();
  if (config.Get("uxr-font-policy") != "restricted")
    return nullptr;
  for (const auto& entry : base::SplitString(config.Get("uxr-font-whitelist"), ",",
                                            base::TRIM_WHITESPACE,
                                            base::SPLIT_WANT_NONEMPTY)) {
    if (const auto* data = GetFontData(description, AtomicString(String::FromUtf8(entry)),
                                       AlternateFontName::kNoAlternate))
      return data;
  }
  // A missing installed pool must not fall back to an excluded host font, or
  // leave Blink's mandatory last-resort font null. Skia's empty face has no
  // host glyphs and keeps this failure bounded; no real font is fabricated.
  const auto* empty = MakeGarbageCollected<FontPlatformData>(
      SkTypeface::MakeEmpty(), std::string(), description.EffectiveFontSize(),
      false, false, description.TextRendering(), ResolvedFontFeatures(),
      description.Orientation());
  return FontDataFromFontPlatformData(empty, description.SubpixelAscentDescent());
}

const SimpleFontData* FontCache::Fallbac.text:
const SimpleFontData* FontCache::FallbackFontForCharacter(
    const FontDescription& description,
    UChar32 lookup_char,
    const SimpleFontData* font_data_to_substitute,
    FontFallbackPriority fallback_priority) {
  TRACE_EVENT0("fonts", "FontCache::FallbackFontForCharacter");

  // In addition to PUA, do not perform fallback for non-characters either. Some
  // of these are sentinel characters to detect encodings and do appear on
  // websites. More details on
  // http://www.unicode.org/faq/private_use.html#nonchar1 - See also
  // crbug.com/862352 where performing fallback for U+FFFE causes a memory
  // regression.
  if (Character::IsPrivateUse(lookup_char) ||
      Character::IsNonCharacter(lookup_char))
    return nullptr;
  base::ElapsedTimer timer;
  if (base::UxrConfig::GetInstance().Get("uxr-font-policy") == "restricted") {
    // Search the installed pool in explicit order. PlatformFallback may return
    // an arbitrary host typeface; do not enter that path in restricted mode.
    for (const auto& entry : base::SplitString(
             base::UxrConfig::GetInstance().Get("uxr-font-whitelist"), ",",
             base::TRIM_WHITESPACE, base::SPLIT_WANT_NONEMPTY)) {
      const auto* candidate = GetFontData(description, AtomicString(String::FromUtf8(entry)),
                                          AlternateFontName::kNoAlternate);
      if (candidate && candidate->GlyphForCharacter(lookup_char))
        return candidate;
    }
    return nullptr;
  }
  const std::string persona = base::UxrConfig::GetInstance().Get("uxr-platform");
  const std::string whitelist = base::UxrConfig::GetInstance().Get("uxr-font-whitelist");
  if (base::UxrConfig::GetInstance().Get("uxr-font-policy").empty() &&
      base::UxrConfig::GetInstance().Get("uxr-synthetic-device-tests") == "true" &&
      (base::EqualsCaseInsensitiveASCII(persona, "windows") ||
       base::EqualsCaseInsensitiveASCII(persona, "win32")) && whitelist.empty()) {
    static constexpr const char* kPersonaFallbackFamilies[] = {
        "Segoe UI Emoji", "Segoe UI Symbol", "Segoe UI", "Arial",
        "Times New Roman", "Microsoft Sans Serif", "Tahoma", "MS Gothic"};
    for (const char* family : kPersonaFallbackFamilies) {
      const SimpleFontData* candidate =
          GetFontData(description, AtomicString(family));
      if (candidate && candidate->GlyphForCharacter(lookup_char))
        return candidate;
    }
    // Missing persona glyphs retain the native system fallback.
  }
  const SimpleFontData* result = PlatformFallbackFontForCharacter(
      description, lookup_char, font_data_to_substitute, fallback_priority);
  base::TimeDelta elapsed = timer.Elapsed();
  bool is_emoji = IsNonTextFallbackPriority(fallback_priority);
  UErrorCode err = U_ZERO_ERROR;
  UScriptCode script = uscript_getScript(lookup_char, &err);
  if (U_FAILURE(err)) {
    script = USCRIPT_INVALID_CODE;
  }
  FontPerformance::AddSystemFallbackFontTime(script, is_emoji, elapsed);
  return result;
}

if (!command_line->HasSwitch(switches:.text:
  if (!command_line->HasSwitch(switches::kProcessType)) {
    const auto set_switch = [&](const char* key, const std::string& value) {
      command_line->RemoveSwitch(key);
      command_line->AppendSwitchASCII(key, value);
    };
    // Reject conflicting caller duplicates; repeated identical values are safe.
    base::CommandLine::SwitchMap seen;
    for (size_t i = 1; i < command_line->argv().size(); ++i) {
      const auto& arg = command_line->argv()[i];
      if (arg == FILE_PATH_LITERAL("--"))
        break;
      const auto parsed = base::CommandLine::FromArgvWithoutProgram({arg});
      for (const auto& [key, value] : parsed.GetSwitches()) {
        if (key == "fingerprint" || key.starts_with("fingerprint-") ||
            key.starts_with("uxr-")) {
          auto found = seen.find(key);
          if (found != seen.end() && found->second != value) {
            std::cerr << "Conflicting fingerprint switch: " << key << std::endl;
            return 1;
          }
          seen[key] = value;
        }
      }
    }
    for (const auto& [key, value] : seen) {
      command_line->RemoveSwitch(key);
      command_line->AppendSwitchNative(key, value);
    }
    // Canonicalize public booleans identically for direct and SDK launches.
    for (const char* key : {"fingerprint-noise", "fingerprint-sapi-voices",
                            "fingerprint-allow-3p-cookies", "fingerprint-windows-font-metrics",
                            "fingerprint-reduced-motion", "fingerprint-reduced-transparency",
                            "fingerprint-inverted-colors", "uxr-reduced-motion",
                            "uxr-reduced-transparency", "uxr-inverted-colors"}) {
      if (!command_line->HasSwitch(key))
        continue;
      const std::string value = base::ToLowerASCII(command_line->GetSwitchValueASCII(key));
      if (value == "off" || value == "false" || value == "0" ||
          value == "disable" || value == "disabled")
        set_switch(key, "false");
      else if (value.empty() || value == "true" || value == "1" ||
               value == "on" || value == "enable" || value == "enabled")
        set_switch(key, "true");
    }

    struct Alias { const char* fp; const char* uxr; };
    static constexpr Alias kAliases[] = {
      {"fingerprint-gpu-backend",         "uxr-gpu-backend"},
      {"fingerprint-font-policy",         "uxr-font-policy"},
      {"fingerprint-font-whitelist",      "uxr-font-whitelist"},
      {"fingerprint-audio-render",        "uxr-audio-render"},
      {"fingerprint-audio-seed",          "uxr-audio-seed"},
      {"fingerprint-timer-resolution",    "uxr-timer-resolution"},
      {"fingerprint-max-touch-points",    "uxr-max-touch-points"},
      {"fingerprint-reduced-motion",      "uxr-reduced-motion"},
      {"fingerprint-reduced-transparency", "uxr-reduced-transparency"},
      {"fingerprint-inverted-colors",     "uxr-inverted-colors"},
      {"fingerprint-color-scheme",        "uxr-color-scheme"},
      {"fingerprint-preferred-contrast",  "uxr-preferred-contrast"},
      {"fingerprint-forced-colors",       "uxr-forced-colors"},
      {"fingerprint-pointer",             "uxr-pointer"},
      {"fingerprint-hover",               "uxr-hover"},
      {"fingerprint-hdr",                 "uxr-hdr"},
      {"fingerprint-keyboard-layout",     "uxr-keyboard-layout"},
      {"fingerprint-gpu-vendor",          "uxr-webgl-vendor"},
      {"fingerprint-gpu-renderer",         "uxr-webgl-renderer"},
      {"disable-gpu-fingerprint",           "uxr-disable-gpu-fingerprint"},
      {"fingerprint-hardware-concurrency", "uxr-hw-concurrency"},
      {"fingerprint-device-memory",       "uxr-device-memory"},
      {"fingerprint-screen-width",        "uxr-screen-width"},
      {"fingerprint-screen-height",       "uxr-screen-height"},
      {"fingerprint-brand",               "uxr-ua-brand"},
      {"fingerprint-brand-version",        "uxr-ua-brand-version"},
      {"fingerprint-platform-version",    "uxr-ua-platform-version"},
      {"fingerprint-timezone",            "uxr-timezone"},
      {"fingerprint-storage-quota",        "uxr-storage-quota"},
      {"fingerprint-taskbar-height",      "uxr-taskbar-height"},
      {"fingerprint-windows-font-metrics", "uxr-windows-font-metrics"},
      {"fingerprint-webrtc-ip",           "uxr-webrtc-ip"},
      {"fingerprint-geolocation",         "uxr-geolocation"},
      {"fingerprint-codec-h264",          "uxr-codec-h264"},
      {"fingerprint-codec-vp8",           "uxr-codec-vp8"},
      {"fingerprint-codec-vp9",           "uxr-codec-vp9"},
      {"fingerprint-codec-av1",           "uxr-codec-av1"},
      {"fingerprint-codec-hevc",          "uxr-codec-hevc"},
      {"fingerprint-devtools-runtime-suppression",
                                             "uxr-devtools-runtime-suppression"},
      {"fingerprint-canvas-bridge",        "uxr-canvas-bridge"},
      {"fingerprint-canvas-bridge-unsafe", "uxr-canvas-bridge-unsafe"},
    };
    for (const auto& a : kAliases) {
      if (command_line->HasSwitch(a.fp) &&
          !command_line->HasSwitch(a.uxr)) {
        command_line->AppendSwitchNative(
            a.uxr, command_line->GetSwitchValueNative(a.fp));
      }
    }

    if (command_line->HasSwitch("fingerprint-locale") &&
        !command_line->HasSwitch("uxr-languages")) {
      command_line->AppendSwitchASCII("uxr-languages",
          command_line->GetSwitchValueASCII("fingerprint-locale"));
    }

    // Canonicalize the public off spellings before any consumer sees them.
    if (command_line->HasSwitch("fingerprint")) {
      const std::string mode = base::ToLowerASCII(
          command_line->GetSwitchValueASCII("fingerprint"));
      if (mode == "off" || mode == "false" || mode == "0" ||
          mode == "disable" || mode == "disabled") {
        set_switch("fingerprint", "off");
        command_line->RemoveSwitch("fingerprint-platform");
      }
    }

    if (command_line->HasSwitch("uxr-ua-brand")) {
      const std::string brand = base::ToLowerASCII(
          command_line->GetSwitchValueASCII("uxr-ua-brand"));
      if (brand == "chrome" || brand == "google chrome")
        set_switch("uxr-ua-brand", "Google Chrome");
      else if (brand == "edge" || brand == "microsoft edge")
        set_switch("uxr-ua-brand", "Microsoft Edge");
      else if (brand == "opera")
        set_switch("uxr-ua-brand", "Opera");
      else if (brand == "vivaldi")
        set_switch("uxr-ua-brand", "Vivaldi");
    }
    // Chrome's brand version is its engine version. Other brands have their
    // own version and must not change the Chromium token or GREASE seed.
    const std::string brand = command_line->GetSwitchValueASCII("uxr-ua-brand");
    if ((brand.empty() || brand == "Google Chrome" || brand == "Chromium") &&
        command_line->HasSwitch("uxr-ua-brand-version") &&
        !command_line->HasSwitch("uxr-ua-full-version")) {
      command_line->AppendSwitchASCII("uxr-ua-full-version",
          command_line->GetSwitchValueASCII("uxr-ua-brand-version"));
    }

    if (command_line->HasSwitch("fingerprint-platform")) {
      const std::string alias = base::ToLowerASCII(
          command_line->GetSwitchValueASCII("fingerprint-platform"));
      std::string platform;
      std::string ua_platform;
      std::string ua_os;
      std::string platform_version;
      bool native_platform = false;
      if (alias == "windows" || alias == "win32") {
        platform = "Win32";
        ua_platform = "Windows";
        ua_os = "Windows NT 10.0; Win64; x64";
        platform_version = "10.0.0";
#if BUILDFLAG(IS_WIN)
        native_platform = true;
#endif
      } else if (alias == "macos" || alias == "macintel") {
        platform = "MacIntel";
        ua_platform = "macOS";
        ua_os = "Macintosh; Intel Mac OS X 10_15_7";
        platform_version = "10.15.7";
#if BUILDFLAG(IS_MAC)
        native_platform = true;
#endif
      } else if (alias == "linux" || alias == "linux x86_64") {
        platform = "Linux x86_64";
        ua_platform = "Linux";
        ua_os = "X11; Linux x86_64";
#if BUILDFLAG(IS_LINUX)
        native_platform = true;
#endif
      }
      if (!platform.empty()) {
        const auto append_default = [&](const char* name,
                                        const std::string& value) {
          if (!command_line->HasSwitch(name))
            command_line->AppendSwitchASCII(name, value);
        };
        if (!native_platform) {
          // Cross-OS templates prevent host fallback; they are not device data.
          append_default("uxr-platform", platform);
          append_default("uxr-ua-os", ua_os);
          append_default("uxr-ua-platform", ua_platform);
          append_default("uxr-ua-arch", "x86");
          append_default("uxr-ua-bitness", "64");
          append_default("uxr-ua-model", "");
          append_default("uxr-ua-wow64", "false");
          append_default("uxr-ua-platform-version", platform_version);
        } else if (alias == "linux x86_64") {
          // This alias explicitly declares an x86_64 Linux persona.
          append_default("uxr-platform", platform);
          append_default("uxr-ua-os", ua_os);
          append_default("uxr-ua-platform", ua_platform);
          append_default("uxr-ua-arch", "x86");
          append_default("uxr-ua-bitness", "64");
        }
      }
    }

    if (command_line->HasSwitch("fingerprint")) {
      std::string seed =
          command_line->GetSwitchValueASCII("fingerprint");
      if (seed.empty()) {
        seed = command_line->GetSwitchValueASCII("uxr-fingerprint-seed");
        if (seed.empty())
          seed = command_line->GetSwitchValueASCII("uxr-canvas-seed");
        if (seed.empty()) {
          uint64_t random_seed = base::RandUint64();
          if (random_seed == 0)
            random_seed = 1;
          seed = base::NumberToString(random_seed);
        }
      }
      if (!seed.empty() && seed != "off") {
        set_switch("uxr-fingerprint-enabled", "true");
        set_switch("uxr-webgl-fingerprint", "true");
        if (!command_line->HasSwitch("uxr-fingerprint-seed"))
          command_line->AppendSwitchASCII("uxr-fingerprint-seed", seed);
        if (!command_line->HasSwitch("uxr-canvas-seed"))
          command_line->AppendSwitchASCII("uxr-canvas-seed", seed);
        if (!command_line->HasSwitch("uxr-audio-seed"))
          command_line->AppendSwitchASCII("uxr-audio-seed", seed);
      }
    }

    const bool public_fingerprint =
        command_line->GetSwitchValueASCII("uxr-fingerprint-enabled") == "true";
    if (public_fingerprint || command_line->HasSwitch("uxr-screen-width") ||
        command_line->HasSwitch("uxr-screen-height") ||
        command_line->HasSwitch("uxr-screen-avail-width") ||
        command_line->HasSwitch("uxr-screen-avail-height") ||
        command_line->HasSwitch("uxr-taskbar-height")) {
      const auto append_default = [&](const char* key, const char* value) {
        if (!command_line->HasSwitch(key))
          command_line->AppendSwitchASCII(key, value);
      };
      std::string platform = base::ToLowerASCII(
          command_line->GetSwitchValueASCII("uxr-ua-platform"));
      if (platform.empty())
        platform = base::ToLowerASCII(
            command_line->GetSwitchValueASCII("uxr-platform"));
      if (platform.empty()) {
#if BUILDFLAG(IS_WIN)
        platform = "windows";
#elif BUILDFLAG(IS_MAC)
        platform = "macos";
#else
        platform = "linux";
#endif
      }
      const bool mac = platform == "macos" || platform == "macintel";
      const bool win = platform == "windows" || platform == "win32";
      // Public launch defaults are independent of noise seeds. Explicit
      // synthetic tests retain their opt-in, seeded hardware/geometry pools.
      if (command_line->GetSwitchValueASCII("uxr-synthetic-device-tests") != "true") {
        if (public_fingerprint) {
          append_default("uxr-hw-concurrency", "8");
          append_default("uxr-device-memory", "8");
        }
        append_default("uxr-screen-width", mac ? "1440" : "1920");
        append_default("uxr-screen-height", mac ? "900" : "1080");
        if (!command_line->HasSwitch("uxr-screen-avail-height"))
          append_default("uxr-taskbar-height", win ? "48" : mac ? "95" : "0");
      }
      if (public_fingerprint)
        append_default("uxr-storage-quota", "102400");
      if (public_fingerprint && win && !command_line->HasSwitch("fingerprint-sapi-voices"))
        append_default("uxr-voices", "true");
    }

    if (command_line->HasSwitch("fingerprint-noise") &&
        command_line->GetSwitchValueASCII("fingerprint-noise") == "false") {
      // Disable perturbation, not persona selection. All seeds stay intact.
      set_switch("uxr-disable-fingerprint-noise", "");
    }

    if (command_line->HasSwitch("fingerprint-sapi-voices")) {
      const std::string value = base::ToLowerASCII(
          command_line->GetSwitchValueASCII("fingerprint-sapi-voices"));
      if (value == "false" || value == "0" || value == "off")
        command_line->RemoveSwitch("uxr-voices");
      else
        set_switch("uxr-voices", "true");
    }

    if (command_line->HasSwitch("fingerprint") &&
        command_line->GetSwitchValueASCII("fingerprint") == "off") {
      // Explicit regional settings are independent of fingerprint spoofing.
      const bool has_timezone = command_line->HasSwitch("uxr-timezone");
      const bool has_languages = command_line->HasSwitch("uxr-languages");
      const std::string timezone = command_line->GetSwitchValueASCII("uxr-timezone");
      const std::string languages = command_line->GetSwitchValueASCII("uxr-languages");
      const auto& sws = command_line->GetSwitches();
      std::vector<std::string> uxr_keys;
      for (const auto& s : sws) {
        if (s.first.compare(0, 4, "uxr-") == 0)
          uxr_keys.push_back(s.first);
      }
      for (const auto& k : uxr_keys)
        command_line->RemoveSwitch(k);
      command_line->AppendSwitchASCII("uxr-fingerprint-off", "true");
      command_line->RemoveSwitch("fingerprint-platform");
      if (has_timezone)
        command_line->AppendSwitchASCII("uxr-timezone", timezone);
      if (has_languages)
        command_line->AppendSwitchASCII("uxr-languages", languages);
      // GPU identity and readback noise otherwise have enabled defaults.
      command_line->AppendSwitch("uxr-webgl-real");
      set_switch("uxr-disable-fingerprint-noise", "");
    }

    if (command_line->HasSwitch("uxr-languages")) {
      std::vector<std::string> languages;
      bool valid = true;
      for (const auto& value : base::SplitString(
               command_line->GetSwitchValueASCII("uxr-languages"), ",",
               base::TRIM_WHITESPACE, base::SPLIT_WANT_NONEMPTY)) {
        const auto tag =
            base::i18n::LanguageTagConverter::GetInstance().FromString(value);
        if (!tag || tag->language_subtag() == "und") {
          valid = false;
          break;
        }
        const std::string canonical(tag->tag_string());
        bool duplicate = false;
        for (const auto& language : languages)
          duplicate |= language == canonical;
        if (!duplicate)
          languages.push_back(canonical);
      }
      if (valid && !languages.empty()) {
        const std::string normalized = base::JoinString(languages, ",");
        set_switch("uxr-languages", normalized);
        set_switch(switches::kAcceptLang, normalized);
      } else {
        command_line->RemoveSwitch("uxr-languages");
      }
    }

    // Set actual native window bounds. Getter overrides cannot resize a window
    // or supply valid negative monitor coordinates. Native caller flags win.
    constexpr char kWindowSize[] = "window-size";
    constexpr char kWindowPosition[] = "window-position";
    if (command_line->HasSwitch("uxr-outer-width") &&
        command_line->HasSwitch("uxr-outer-height") &&
        !command_line->HasSwitch(kWindowSize)) {
      command_line->AppendSwitchASCII(
          kWindowSize, command_line->GetSwitchValueASCII("uxr-outer-width") +
                           "," + command_line->GetSwitchValueASCII("uxr-outer-height"));
    }
    // An explicit native position must also win inside device emulation;
    // otherwise the real window and its web-exposed position would disagree.
    if (command_line->HasSwitch(kWindowPosition)) {
      command_line->RemoveSwitch("uxr-window-x");
      command_line->RemoveSwitch("uxr-window-y");
    } else if ((command_line->HasSwitch("uxr-window-x") ||
         command_line->HasSwitch("uxr-window-y")) &&
        !command_line->HasSwitch(kWindowPosition)) {
      const std::string x = command_line->HasSwitch("uxr-window-x")
                                ? command_line->GetSwitchValueASCII("uxr-window-x") : "0";
      const std::string y = command_line->HasSwitch("uxr-window-y")
                                ? command_line->GetSwitchValueASCII("uxr-window-y") : "0";
      command_line->AppendSwitchASCII(kWindowPosition, x + "," + y);
    }

    if (command_line->HasSwitch("fingerprint-allow-3p-cookies") &&
        command_line->GetSwitchValueASCII("fingerprint-allow-3p-cookies") != "false" &&
        command_line->GetSwitchValueASCII("fingerprint-allow-3p-cookies") != "0") {
      // This native switch is presence-based: appending '=false' ENABLES the
      // phaseout. CookieSettings consumes our explicit, non-persistent opt-in.
      command_line->RemoveSwitch("test-third-party-cookie-phaseout");
      set_switch("uxr-allow-3p-cookies", "true");
      constexpr char kDisableFeatures[] = "disable-features";
      std::string disabled = command_line->GetSwitchValueASCII(kDisableFeatures);
      auto features = base::SplitString(disabled, ",", base::TRIM_WHITESPACE,
                                        base::SPLIT_WANT_NONEMPTY);
      std::erase(features, "ForceThirdPartyCookieBlocking");
      disabled = base::JoinString(features, ",");
      command_line->RemoveSwitch(kDisableFeatures);
      if (!disabled.empty())
        disabled += ",";
      disabled += "ForceThirdPartyCookieBlocking";
      command_line->AppendSwitchASCII(kDisableFeatures, disabled);
    }

    // Apply the native socket policy for direct browser launches too. HTTP
    // proxying or SOCKS TCP authentication cannot carry arbitrary WebRTC UDP.
    // An explicit caller policy retains Chromium's normal precedence.
    if (!command_line->HasSwitch(switches::kNoProxyServer) &&
        (command_line->HasSwitch(switches::kProxyServer) ||
         command_line->HasSwitch(switches::kProxyPacUrl) ||
         command_line->HasSwitch(switches::kProxyAutoDetect)) &&
        !command_line->HasSwitch(switches::kForceWebRtcIPHandlingPolicy)) {
      command_line->AppendSwitchASCII(switches::kForceWebRtcIPHandlingPolicy,
                                      "disable_non_proxied_udp");
    }
  }

